<template><div class="page-shell"><header class="page-header compact"><div><h1>我的歌单</h1><p class="page-subtitle">管理自己创建的歌单。</p></div></header><form class="inline-form" @submit.prevent="create"><input v-model.trim="name" maxlength="120" placeholder="新歌单名称" aria-label="新歌单名称" required><button class="primary-button" type="submit"><Plus :size="18" /><span>创建</span></button></form><p v-if="error" class="form-error" role="alert">{{error}}</p><StateMessage v-if="state==='loading'" state="loading" message="正在加载歌单…" /><div v-else class="playlist-list"><router-link v-for="item in playlists" :key="item.id" class="playlist-item" :to="`/library/playlists/${item.id}`"><ListMusic :size="22" /><span><strong>{{item.name}}</strong><small>{{item.description||'暂无描述'}}</small></span><ChevronRight :size="18" /></router-link><p v-if="!playlists.length" class="empty-state">还没有创建歌单。</p></div></div></template>
<script>
import { ChevronRight,ListMusic,Plus } from 'lucide-vue'; import { library } from '../library/client.js'; import { problemMessage } from '../ui/problem-message.js'; import StateMessage from '../components/StateMessage.vue';
export default {name:'PlaylistsView',components:{ChevronRight,ListMusic,Plus,StateMessage},data:()=>({state:'loading',playlists:[],name:'',error:''}),async mounted(){await this.load();},methods:{async load(){this.state='loading';try{this.playlists=await library.playlists();this.state='ready';}catch(problem){this.state='error';this.error=problemMessage(problem);}},async create(){try{const item=await library.createPlaylist({name:this.name,description:'',visibility:'PRIVATE'});this.playlists.unshift(item);this.name='';}catch(problem){this.error=problemMessage(problem);}}}};
</script>
